INSERT INTO News (Type, Date, Theme, Image, Body)
VALUES (N'Технологии', '2026-05-17', N'Honda сделает упор на гибриды', N'Images/News/News_1.jpg',
        N'Honda Motor после полного закрытия всех проектов перспективных электромобилей и списания израсходованных на них впустую почти 10 миллиардов долларов (около 720 миллиардов рублей), приняла к реализации новый план развития, где основной упор будет сделан на гибриды. ;Веха в истории компании будет отмечена и очередным поворотом в дизайне ее продуктов. Как будут выглядеть новые гибридные автомобили Honda для компании североамериканского рынка демонстрируют представленные публично опытные образцы среднеразмерного седана и компактного кроссовера с незатейливыми названиями Honda Hybrid Sedan Prototype и Acura Hybrid SUV Prototype, фактически провозвестники новых поколений Honda Accord и Acura RDX.;В отличие от совершенно оторванных от реальности электромобилей закрытого проекта Honda Zero перспективные гибриды компании имеют обособленные капот и «кабину» с окнами по кругу, и в целом выглядят как нормальные автомобили для жизни.;Honda Hybrid Sedan Prototype отличает силуэт лифтбека без выраженного объема багажника. Вместе с гладкими поверхностями кузова, сочетающимися с острыми гранями, образ седана напоминает о выполненном в похожей стилистике китайский Changan Uni-V. Передняя часть концепт-кара имеет обратный уклон при виде в профиль, привлекает внимание большая по площади решетка радиатора в форме трапеции. В целом экстерьером автомобиль напоминает спорткары.;Облик кроссовера Acura Hybrid SUV Prototype также решен в спортивном стиле, но иначе. Переднеприводному кроссоверу с помощью ряда дизайнерских приемов попытались придать пропорции заднеприводного. Это сильный выпуклый рельеф на задних крыльях переходящий в интегрированный спойлер на пятой двери, суженное по горизонтали заднее окно, и это низкий капот состыкованный с передними стойками крыши ярко выраженной гранью. При этом высота крыши над задним рядом сидений находится на одном уровне с передним. Вместо привычной для Acura пятиконечной радиаторной решетки установлена решетка трапецевидной формы у нижнего края бампера — еще одна отсылка к автоспорту.;Новые Honda Accord и Acura RDX с гибридными трансмиссиями будут выпущены в течение следующей пары лет. Трансмиссия 4WD на них будет предполагать отдельный электромотор на задней оси.;'),
       (N'Технологии', '2026-05-15', N'Toyota начала продавать на внутреннем рынке Японии новый рамный внедорожник',
        N'Images/News/News_2.jpg',
        N'Toyota Motor запустила на внутреннем японском рынке продажи нового рамного внедорожника Land Cruiser FJ.;Напомним, премьера этой модели прошла осенью 2025-го.;В спецификации для Японии машина оснащена 2,7-литровым бензиновым двигателем (163 л.с., 246 Нм) и 6-ступенчатой автоматической коробкой передач. Привод подключаемый полный. Заявленный средний расход топлива — 11,5 л/100 км.;Land Cruiser FJ тяготеет к компактному классу: габаритная длина — 4575 мм, ширина — 1855 мм, высота — 1960 мм, колесная база — 2580 мм.;Несущие лонжероны и поперечины модели относятся к платформе IMV0, модификации которой также используются на пикапе Hilux, внедорожнике Fortuner и вэне Innova.;В Японии Toyota Land Cruiser FJ стоит от 4 500 000 иен (=2,1 млн рублей).;Единственным местом производства нового внедорожника является автозавод Toyota Motor Thailand Co Ltd в Таиланде.;'),
       (N'Автоспорт', '2020-10-14', N'Subaru представила карбоновую WRX STI для нового эпизода Джимханы',
        N'Images/News/News_3.jpg',
        N'Североамериканское подразделение Subaru и компания Vermont SportsCar представили уникальную версию седана WRX STI. Он снимется для нового эпизода Джимханы, в котором легендарного специалиста в этом деле Кэна Блока заменит пилот Subaru Motorsports USA Трэвис Пастрана, известный своими выступлениями в гоночной серии NASCAR. Джимхана — вид автоспорта со сложными трассами, конфигурация которых определяется конусами, покрышками и препятствиями, при этом водитель должен показывать дрифт и развороты на 360 градусов.;От стандартной машины подготовленный WRX STI для Джимханы отличается углепластиковым обвесом с модифицированными бамперами, аэродинамическими элементами в виде крылышек и закрылков, большим задним антикрылом, заниженными боковыми фартуками, расширенными колесными арками, выведенной через капот выпускной системой двигателя, а также развитым диффузором. Автомобиль обут в легкосплавные колесные диски с шинами Yokohama Advan, заднее стекло украшает число 199 — традиционный счастливый номер гонщика.;Под капотом у прототипа трудится 2,5-литровый оппозитный 4-цилиндровый турбированный мотор, о его характеристиках информации нет.;В салоне машины установлены гоночный руль и каркас безопасности.;Subaru считает этот автомобиль «самым диким когда-либо построенным WRX STI».;');